(() => {
  'use strict';
  if (!document.getElementById('mmd-model-home-v3') || document.getElementById('mmd-media-upload-v1')) return;
  const controllers=new Set(),transfers=new Set(),objectUrls=new Set();
  async function request(url,options={}){const controller=new AbortController();controllers.add(controller);try{return await fetch(url,{...options,signal:controller.signal});}finally{controllers.delete(controller);}}
  const MAX_BYTES=25*1024*1024,MAX_PHOTOS=8,MAX_CLIPS=1,DRAFT='mmd:model-media-upload:v1';
  const imageTypes=new Set(['image/jpeg','image/png','image/webp','image/heic','image/heif']);
  const clipTypes=new Set(['video/mp4','video/quicktime','video/webm']);
  const root=document.createElement('section');root.id='mmd-media-upload-v1';root.setAttribute('aria-label','ส่งรูปและคลิปให้ MMD ตรวจ');
  root.innerHTML='<h2>ส่งรูปและคลิป Public ให้ MMD ตรวจ</h2><p>Public: รูปสูงสุด 8 รูป · คลิปสูงสุด 1 คลิป · ไฟล์ละไม่เกิน 25 MB</p><p class="mmu-note">แนะนำภาพไลฟ์สไตล์ที่เป็นตัวเอง เห็นใบหน้าชัด ยิ้มสดใสหรือดูเท่ และมีภาพเล่นกีฬาได้ ควรให้ผู้อื่นช่วยถ่าย เลี่ยงภาพสตูดิโอ แว่นดำ หมวก เซลฟี่ที่บังหน้า แต่งหน้าจัด และรูปคู่ คำแนะนำนี้ไม่ใช่การคัดออกอัตโนมัติ</p><p class="mmu-note">ไฟล์ชุดนี้เป็น Public candidate และจะยังไม่แสดงต่อสาธารณะจนกว่า Studio จะอนุมัติ คลิปไม่บังคับ ส่งรูปก่อนได้</p><label class="mmu-native-picker"><span>เลือกไฟล์ Public</span><input id="mmu-files" type="file" multiple accept="image/jpeg,image/png,image/webp,image/heic,image/heif,video/mp4,video/quicktime,video/webm"></label><button id="mmu-upload" type="button" disabled hidden>ส่ง Public media</button><p id="mmu-state" role="status" aria-live="polite"></p><ul id="mmu-list"></ul><section class="mmu-private"><h2>ส่ง Private media สำหรับ SIGIL</h2><p>Private: รูปสูงสุด 2 รูป · คลิปสูงสุด 1 คลิป · ไฟล์ละไม่เกิน 25 MB</p><p class="mmu-note">แยกจาก Public โดยสิ้นเชิง ไฟล์จะเข้า private storage และรอ Per ตรวจ ไม่เกิด public URL และไม่ถูกย้ายไป Public อัตโนมัติ คลิปไม่บังคับ</p><label class="mmu-consent"><input id="mmu-private-consent" type="checkbox"><span>ยินยอมให้ MMD เก็บและตรวจไฟล์นี้เพื่อใช้ในพื้นที่ Private SIGIL ตามสิทธิ์ที่กำหนด</span></label><label class="mmu-native-picker"><span>เลือกไฟล์ Private</span><input id="mmu-private-files" type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4"></label><button id="mmu-private-upload" type="button" disabled hidden>ส่ง Private media</button><p id="mmu-private-state" role="status" aria-live="polite"></p><ul id="mmu-private-list"></ul></section>';
  (document.querySelector('#mmd-model-self-service .mss__shell')||document.getElementById('mmd-model-home-v3')).append(root);
  const input=root.querySelector('#mmu-files'),button=root.querySelector('#mmu-upload'),state=root.querySelector('#mmu-state'),list=root.querySelector('#mmu-list'),privateInput=root.querySelector('#mmu-private-files'),privateButton=root.querySelector('#mmu-private-upload'),privateState=root.querySelector('#mmu-private-state'),privateList=root.querySelector('#mmu-private-list'),privateConsent=root.querySelector('#mmu-private-consent');let queue=[],privateQueue=[],current=[];
  const say=(text,error=false)=>{state.textContent=text;state.className=error?'mmu-error':''};
  const normalizedMime=file=>{let type=String(file?.type||'').trim().toLowerCase();if(type==='image/jpg')type='image/jpeg';if(imageTypes.has(type)||clipTypes.has(type))return type;const name=String(file?.name||'').toLowerCase(),ext=(name.match(/.([a-z0-9]+)$/)||[])[1]||'';return({jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',heic:'image/heic',heif:'image/heif',mp4:'video/mp4',mov:'video/quicktime',webm:'video/webm'})[ext]||type};
  const kind=file=>{const type=normalizedMime(file);return imageTypes.has(type)?'photo':clipTypes.has(type)?'clip':''};
  const mediaKind=item=>item.media_type==='intro_video'?'clip':'photo';
  const retained=item=>!['rejected','deleted','archived'].includes(String(item.review_status||'').toLowerCase());
  function saveDraft(){try{sessionStorage.setItem(DRAFT,JSON.stringify(queue.filter(x=>x.mediaId).map(x=>({media_id:x.mediaId,name:x.file.name,status:x.status}))))}catch{}}
  function loadDraft(){try{return JSON.parse(sessionStorage.getItem(DRAFT)||'[]')}catch{return[]}}
  function row(item,target=list,retryAction=uploadOne){const li=document.createElement('li');li.innerHTML='<div class="mmu-row"><span class="mmu-name"></span><button type="button" hidden>ลองอีกครั้ง</button></div><progress max="100" value="0"></progress><p></p>';li.querySelector('.mmu-name').textContent=item.file.name;if(target!==privateList){const preview=document.createElement(item.type==='clip'?'video':'img');preview.className='mmu-preview';preview.src=URL.createObjectURL(item.file);objectUrls.add(preview.src);if(item.type==='clip'){preview.muted=true;preview.playsInline=true;preview.controls=true}else preview.alt='ตัวอย่างไฟล์ที่เลือก';li.append(preview);}item.node=li;item.progress=li.querySelector('progress');item.message=li.querySelector('p');const retry=li.querySelector('button');retry.onclick=()=>retryAction(item);item.retry=retry;target.append(li);return item}
  function counts(extra=[]){const all=current.filter(item=>item.self_managed&&retained(item)).map(mediaKind).concat(extra.map(x=>kind(x.file)));return{photos:all.filter(x=>x==='photo').length,clips:all.filter(x=>x==='clip').length}}
  function privateCounts(extra=[]){const all=current.filter(item=>!item.self_managed&&retained(item)&&['private_gallery','flash_preview'].includes(item.media_type)).map(item=>item.file_type==='video/mp4'?'clip':'photo').concat(extra.map(x=>kind(x.file)));return{photos:all.filter(x=>x==='photo').length,clips:all.filter(x=>x==='clip').length}}
  async function readBack(){const response=await request('/v1/model/media',{credentials:'include',cache:'no-store',headers:{accept:'application/json'}}),data=await response.json().catch(()=>null);if(!response.ok||!data?.ok||!Array.isArray(data.media))throw new Error('อ่านรายการที่ส่งแล้วไม่สำเร็จ');current=data.media;window.dispatchEvent(new CustomEvent('mmd:model-media-updated'));const pending=current.filter(x=>x.review_status==='pending_review').length;say('อ่านรายการล่าสุดแล้ว'+(pending?' · รอตรวจ '+pending+' ไฟล์':''));return data.media}
  function validate(files){const seen=new Set(),accepted=[];for(const file of files){const type=kind(file);if(!type)throw new Error('รองรับเฉพาะ JPG, PNG, WebP, HEIC, MP4, MOV และ WebM');if(file.size<1||file.size>MAX_BYTES)throw new Error('ไฟล์ '+file.name+' ต้องมีขนาดไม่เกิน 25 MB');const key=[file.name,file.size,file.lastModified].join(':');if(seen.has(key))continue;seen.add(key);accepted.push({file,type,contentType:normalizedMime(file)})}const total=counts(accepted);if(total.photos>MAX_PHOTOS)throw new Error('เลือกรูปได้สูงสุด 8 รูป รวมรายการที่ส่งไว้แล้ว');if(total.clips>MAX_CLIPS)throw new Error('เลือกคลิปได้สูงสุด 1 คลิป รวมรายการที่ส่งไว้แล้ว');return accepted}
  function validatePrivate(files){const seen=new Set(),accepted=[];for(const file of files){const type=kind(file);const contentType=normalizedMime(file);if(!type||!['image/jpeg','image/png','image/webp','video/mp4'].includes(contentType))throw new Error('Private รองรับ JPG, PNG, WebP และ MP4');if(file.size<1||file.size>MAX_BYTES)throw new Error('ไฟล์ '+file.name+' ต้องมีขนาดไม่เกิน 25 MB');const key=[file.name,file.size,file.lastModified].join(':');if(seen.has(key))continue;seen.add(key);accepted.push({file,type,contentType})}const total=privateCounts(accepted);if(total.photos>2)throw new Error('Private เลือกรูปได้สูงสุด 2 รูป รวมรายการที่ส่งไว้แล้ว');if(total.clips>1)throw new Error('Private เลือกคลิปได้สูงสุด 1 คลิป รวมรายการที่ส่งไว้แล้ว');return accepted}
  function putWithProgress(item,url){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();transfers.add(xhr);xhr.onloadend=()=>transfers.delete(xhr);xhr.onabort=()=>reject(new Error("ยกเลิกการอัปโหลดแล้ว"));xhr.open('PUT',url);xhr.withCredentials=true;xhr.setRequestHeader('content-type',item.contentType||normalizedMime(item.file));xhr.upload.onprogress=e=>{if(e.lengthComputable)item.progress.value=Math.round(e.loaded/e.total*100)};xhr.onload=()=>{let data=null;try{data=JSON.parse(xhr.responseText)}catch{}if(xhr.status>=200&&xhr.status<300&&data?.ok)resolve(data);else reject(new Error(data?.error||'ส่งไฟล์ไม่สำเร็จ'))};xhr.onerror=()=>reject(new Error('เครือข่ายขัดข้อง กรุณาลองอีกครั้ง'));xhr.send(item.file)})}
  async function uploadOne(item){if(item.busy||item.status==='done')return;item.busy=true;item.retry.hidden=true;item.message.className='';item.message.textContent='กำลังขอสิทธิ์ส่งไฟล์…';try{if(!item.plan||Date.parse(item.plan.expires_at)<=Date.now()+5000){const response=await request('/v1/model/media/upload-url',{method:'POST',credentials:'include',headers:{'content-type':'application/json'},body:JSON.stringify({media_type:item.type==='clip'?'intro_video':'public_gallery',file_name:item.file.name,content_type:item.contentType||normalizedMime(item.file),file_size_bytes:item.file.size})});const plan=await response.json().catch(()=>null);if(!response.ok||!plan?.ok)throw new Error(plan?.error||'ขอสิทธิ์ส่งไฟล์ไม่สำเร็จ');item.plan=plan}item.message.textContent='กำลังส่งไฟล์…';const result=await putWithProgress(item,item.plan.upload_url);item.mediaId=result.media?.media_id||item.plan.media_id;item.status='done';item.progress.value=100;item.message.className='mmu-ok';item.message.textContent='ส่งแล้ว · รอ Studio ตรวจ';saveDraft();await readBack()}catch(error){item.status='error';item.message.className='mmu-error';item.message.textContent='ยังส่งไม่ได้: '+(error.message||'unknown_error');item.retry.hidden=false}finally{item.busy=false}}
  async function uploadPrivate(item){if(item.busy||item.status==='done')return;item.busy=true;item.retry.hidden=true;item.message.className='';item.message.textContent='กำลังขอสิทธิ์ส่ง Private media…';try{if(!privateConsent.checked)throw new Error('กรุณายืนยัน consent สำหรับ Private media');if(!item.uploadRef)item.uploadRef='media_'+crypto.randomUUID().replace(/-/g,'');if(!item.plan||(!item.plan.upload_complete&&Date.parse(item.plan.expires_at)<=Date.now()+5000)){const response=await request('/v1/model/media/private-upload-plan',{method:'POST',credentials:'include',headers:{'content-type':'application/json'},body:JSON.stringify({upload_ref:item.uploadRef,purpose:'sigil_private_profile',consent_version:'mmd-private-media-v1-20260927',file_name:item.file.name,content_type:item.contentType||normalizedMime(item.file),file_size_bytes:item.file.size})});const plan=await response.json().catch(()=>null);if(!response.ok||!plan?.ok)throw new Error(plan?.error||'ขอสิทธิ์ส่ง Private media ไม่สำเร็จ');item.plan=plan}if(!item.plan.upload_complete){item.message.textContent='กำลังส่งเข้า private storage…';const response=await request(item.plan.upload_endpoint,{method:'POST',credentials:'include',headers:{'content-type':item.contentType||normalizedMime(item.file)},body:item.file}),result=await response.json().catch(()=>null);if(!response.ok||!result?.ok)throw new Error(result?.error||'ส่ง Private media ไม่สำเร็จ')}item.status='done';item.progress.value=100;item.message.className='mmu-ok';item.message.textContent='ส่งแล้ว · รอ Per ตรวจ';await readBack()}catch(error){item.status='error';item.message.className='mmu-error';item.message.textContent='ยังส่งไม่ได้: '+(error.message||'unknown_error');item.retry.hidden=false}finally{item.busy=false}}
  input.addEventListener('change',()=>{try{queue=validate([...input.files]).map(x=>row({...x,status:'ready',mediaId:''}));button.disabled=!queue.length;button.hidden=button.disabled;say(queue.length?'พร้อมส่ง '+queue.length+' ไฟล์':'')}catch(error){input.value='';queue=[];button.disabled=true;button.hidden=true;say(error.message,true)}});
  button.addEventListener('click',async()=>{button.disabled=true;for(const item of queue)await uploadOne(item);button.disabled=!queue.some(x=>x.status==='error');button.hidden=button.disabled});
  privateInput.addEventListener('change',()=>{try{privateQueue=validatePrivate([...privateInput.files]).map(x=>row({...x,status:'ready'},privateList,uploadPrivate));privateButton.hidden=!privateQueue.length;privateButton.disabled=!privateQueue.length||!privateConsent.checked;privateState.textContent=privateQueue.length?'พร้อมส่ง Private '+privateQueue.length+' ไฟล์':'';privateState.className=''}catch(error){privateInput.value='';privateQueue=[];privateButton.disabled=true;privateButton.hidden=true;privateState.textContent=error.message;privateState.className='mmu-error'}});
  privateConsent.addEventListener('change',()=>{privateButton.disabled=!privateQueue.length||!privateConsent.checked});
  privateButton.addEventListener('click',async()=>{privateButton.disabled=true;for(const item of privateQueue)await uploadPrivate(item);privateButton.disabled=!privateQueue.some(x=>x.status==='error');privateButton.hidden=privateButton.disabled});
  window.addEventListener('pagehide',()=>{controllers.forEach(c=>c.abort());transfers.forEach(x=>x.abort());objectUrls.forEach(u=>URL.revokeObjectURL(u));privateQueue=[];privateInput.value='';});
  window.addEventListener('mmd:model-session-ready',()=>readBack().catch(error=>say(error.message,true)));
  readBack().then(()=>{const draft=loadDraft();if(draft.length)say('กู้สถานะรายการเดิมแล้ว · ตรวจสอบกับรายการจากเซิร์ฟเวอร์เรียบร้อย')}).catch(error=>say(error.message,true));
})();
